<?php else: $s=Game::situation($g); ?><?php if($g['stage']==='fim_semana'): ?><article class="panel"><h3>Apito final: <?=e($m['hg'].' × '.$m['ag'])?></h3><a href="/classificacao">Resultados da rodada e tabela →</a></article><?php Presentation::matchStats($g,$m); Presentation::goalHistory($g); endif ?><article class="panel"><p class="tag"><?=e(str_replace('_',' ',strtoupper($g['stage'])))?></p><h2><?=e($s['text'])?></h2><p>Escolha sua atitude. Os custos de tentativa são aplicados mesmo se a intenção falhar; ganhos técnicos são XP.</p><?php form('/decisao/registrar',$g); foreach(Game::choices($g) as $i=>$o): ?><button class="choice" name="option" value="<?=e($i)?>"><b><?=e(chr(65+$i))?></b><span><?=e($o['text'])?><small>Chance <?=e(Game::chance($g,$o))?>% · <?php foreach($o['effects'] as $k=>$v): ?><?=e((in_array($k,Rules::SKILLS,true)?'XP ':'').str_replace('_',' ',$k).' '.($v>=0?'+':'').$v)?>; <?php endforeach ?></small></span></button><?php endforeach ?></form></article>
